def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        if tz is None:
            import datetime
            return datetime.time.fromtimestamp(nanoseconds / 1e9)
        else:
            import datetime
            import pytz
            tz = pytz.timezone(tz)
            dt = datetime.datetime.fromtimestamp(nanoseconds / 1e9, tz)
            return dt.time()
    except (OSError, ValueError) as e:
        raise ValueError(f"Invalid input for hydrate_time: {e}")

def dehydrate_timedelta(value):
