def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError as e:
        raise KeyError(str(key)) from e

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self.__dict__.values())
    else:
        values = []
        for key in keys:
            if isinstance(key, int):
                try:
                    values.append(list(self.__dict__.values())[key])
                except IndexError:
                    raise KeyNotFoundError(f"Index {key} out of range.")
            elif isinstance(key, str):
                try:
                    values.append(self.__dict__[key])
                except KeyError:
                    raise KeyNotFoundError(f"Key '{key}' not found.")
            else:
                raise TypeError(f"Invalid key type: {type(key)}. Expected int or str.")
        return values

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        return dict(self._data)
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._data):
                raise IndexError(f"Index {key} is out of bounds")
            result[list(self._data.keys())[key]] = self._data[list(self._data.keys())[key]]
        else:
            result[key] = self._data.get(key, None)
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    try:
        if len(self.data) < 2:
            raise ValueError("Insufficient data to pop a 16-bit integer")
        high_byte, low_byte = self.data.pop(), self.data.pop()
        return (high_byte << 8) | low_byte
    except Exception as e:
        raise ValueError("Failed to pop a 16-bit integer") from e

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    from collections import namedtuple

    class Point(namedtuple('BasePoint', fields)):
        __slots__ = ()  # Prevent the creation of instance dictionaries to save memory
        srid_mapping = srid_map.copy()

        def __new__(cls, *args, **kwargs):
            try:
                return super(Point, cls).__new__(cls, *args, **kwargs)
            except TypeError as e:
                raise TypeError(f"Error creating {name}: {e}")

        def get_srid(self, key):
            try:
                return self.srid_mapping[key]
            except KeyError:
                raise ValueError(f"SRID key '{key}' not found in srid_map.")

    Point.__name__ = name
    return Point

import warnings
import functools

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.simplefilter('always', DeprecationWarning)  # turn off filter
            warnings.warn(
                f"Call to deprecated function {func.__name__}. {message}",
                category=DeprecationWarning,
                stacklevel=2
            )
            warnings.simplefilter('default', DeprecationWarning)  # reset filter
            return func(*args, **kwargs)
        return wrapper
    return decorator

