def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import re

    if not cmd:
        return cmd

    def fix_shebang(executable):
        try:
            with open(executable, 'r', encoding='utf-8') as file:
                first_line = file.readline().strip()
                if first_line.startswith('#!'):
                    shebang_args = first_line[2:].split()
                    if shebang_args and os.path.basename(shebang_args[0]).lower() in ['python', 'python3']:
                        return [shebang_args[0]] + shebang_args[1:] + [executable]
        except Exception as e:
            # If there's any issue reading the file, just return the original command
            pass
        return [executable]

    if os.name == 'nt' and cmd[0].endswith('.py'):
        return tuple(fix_shebang(cmd[0]) + list(cmd[1:]))

    return cmd

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key(*args, **kwargs)
            try:
                return cache[cache_key]
            except KeyError:
                if lock:
                    with lock:
                        try:
                            return cache[cache_key]
                        except KeyError:
                            value = func(*args, **kwargs)
                            cache[cache_key] = value
                else:
                    value = func(*args, **kwargs)
                    cache[cache_key] = value
                return value
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    first_key = next(iter(self))
    return first_key, self.pop(first_key)

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    if key not in self:
        self[key] = default
    return self[key]

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            if lock:
                with lock:
                    cache_key = key(*args, **kwargs)
                    if cache_key in cache:
                        return cache[cache_key]
                    result = func(*args, **kwargs)
                    cache[cache_key] = result
                    return result
            else:
                cache_key = key(*args, **kwargs)
                if cache_key in cache:
                    return cache[cache_key]
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    try:
        import traceback
        s = traceback.format_exception(type(e), e, e.__traceback__, limit=max_level)
        formatted_lines = []
        for line in s:
            parts = line.split('\\n')
            formatted_parts = []
            for part in parts:
                if len(part) > max_path_level:
                    formatted_parts.append(part[:max_path_level] + '...')
                else:
                    formatted_parts.append(part)
            formatted_lines.append('\\n'.join(formatted_parts))
        return ''.join(formatted_lines)
    except Exception as ex:
        return f"Failed to format exception: {ex}"

