def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []

    for cls in classes:
        if cls not in seen:
            # Check if any of the current class's bases are already in the seen set
            if not any(base in seen for base in cls.__bases__):
                result.append(cls)
                seen.add(cls)
            else:
                # If some bases are already in the result, we need to ensure the order
                # Insert the class before the first base that is already in the seen set
                for i, seen_cls in enumerate(result):
                    if any(base is seen_cls for base in cls.__bases__):
                        result.insert(i, cls)
                        seen.add(cls)
                        break

    return result

