    return ''.join(f"{prefix}{entry}\n" for entry in self.validation_log)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        try:
            if 'type' in inventory:
                self.spec_version = self._extract_version_from_type(inventory['type'])
            else:
                raise ValueError("Inventory does not contain a 'type' value for version extraction.")
        except Exception as e:
            # Fallback to self.spec_version if extraction fails
            print(f"Failed to extract spec version from inventory: {e}")

    # Implement validation logic here
    # Example: Check required fields, validate types, etc.
    # For demonstration, a simple check for required fields is provided.
    required_fields = ['id', 'name', 'version']
    for field in required_fields:
        if field not in inventory:
            raise ValueError(f"Inventory is missing required field: {field}")

    # Additional validation logic can be added as needed.

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    try:
        for manifest in manifest_files:
            for digest in manifest.get_required_digests():
                if digest not in manifest.get_all_digests():
                    raise ValueError(f"Digest {digest} is required but not present in the manifest.")
                if digest not in digests_used:
                    raise ValueError(f"Digest {digest} is present in the manifest but not used.")
    except Exception as e:
        raise ValueError(f"Error checking digests: {str(e)}")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("The prior version must be an instance of InventoryValidator")

    # Compare the items and their versions
    for item_id, current_version in self.items.items():
        if item_id in prior.items:
            if prior.items[item_id] >= current_version:
                raise ValueError(f"Item {item_id} in the prior inventory has a version {prior.items[item_id]} that is not older than the current version {current_version}")
        else:
            raise ValueError(f"Item {item_id} is present in the current inventory but missing in the prior inventory")

    # Check for any items that are missing in the current inventory
    for item_id in prior.items:
        if item_id not in self.items:
            raise ValueError(f"Item {item_id} is present in the prior inventory but missing in the current inventory")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}

    try:
        version_data = inventory.get(version, {})
        for logical_path, files in version_data.items():
            logical_path_map[logical_path] = set(files)
    except Exception as e:
        print(f"An error occurred: {e}")

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list.")

    manifest_file_set = set(manifest_files)

    for file_ref in fixity:
        if file_ref not in manifest_file_set:
            raise ValueError(f"File {file_ref} in fixity block not found in the manifest.")

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except FileNotFoundError:
        raise ValueError(f"The path {path} does not exist.")
    except PermissionError:
        raise ValueError(f"Permission denied to access the path {path}.")
    except Exception as e:
        raise ValueError(f"An error occurred while accessing the path {path}: {e}")

def add_rendition(self, lang, file_path):
    """
    Adds a rendition to the element.

    Parameters:
        lang (str): The language of the rendition.
        file_path (str): The file path of the rendition.
    """
    if not isinstance(lang, str) or not isinstance(file_path, str):
        raise ValueError("Both lang and file_path must be strings.")

    if not hasattr(self, 'renditions'):
        self.renditions = {}

    self.renditions[lang] = file_path

def add_asset(self, basename, file_path):
    """
    Adds an asset to the internal dictionary of assets.

    Parameters:
        basename (str): The basename of the asset file.
        file_path (str): The file path of the asset.
    """
    if not isinstance(basename, str) or not isinstance(file_path, str):
        raise ValueError("Both basename and file_path must be strings.")

    if not self.assets:
        self.assets = {}

    self.assets[basename] = file_path

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise ValueError("Content must be a string")
    try:
        return content.replace('w:st="', 'w-st="')
    except Exception as e:
        raise RuntimeError(f"An error occurred while processing the content: {e}")

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            match = node.xpath(xpath)
            if match:
                return match[0]
        except Exception as e:
            # Handle any exceptions that may occur during xpath evaluation
            print(f"An error occurred while evaluating xpath '{xpath}': {e}")
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = '  ' * indent
    repr_str = f"{indent_str}{self.__class__.__name__}(\n"
    for key, value in self.__dict__.items():
        if isinstance(value, list):
            repr_str += f"{indent_str}  {key}=[\n"
            for item in value:
                if hasattr(item, 'pretty'):
                    repr_str += item.pretty(indent + 2, debug) + ",\n"
                else:
                    repr_str += f"{indent_str}    {item},\n"
            repr_str += f"{indent_str}  ],\n"
        elif hasattr(value, 'pretty'):
            repr_str += f"{indent_str}  {key}={value.pretty(indent + 2, debug)},\n"
        else:
            repr_str += f"{indent_str}  {key}={value},\n"
    repr_str += f"{indent_str})"
    return repr_str

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from copy import deepcopy

    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                # A & (A | B) = A
                if isinstance(right, tuple) and right[0] == '|' and right[1] == left:
                    return left
                # A & (~A | B) = A & B
                elif isinstance(right, tuple) and right[0] == '|' and isinstance(right[1], tuple) and right[1][0] == '~' and right[1][1] == left:
                    return ('&', left, right[2])
            elif op == '|':
                # A | (A & B) = A
                if isinstance(right, tuple) and right[0] == '&' and right[1] == left:
                    return left
                # A | (~A & B) = A | B
                elif isinstance(right, tuple) and right[0] == '&' and isinstance(right[1], tuple) and right[1][0] == '~' and right[1][1] == left:
                    return ('|', left, right[2])
        return expr

    result = []
    for expr in args:
        simplified_expr = apply_absorption(expr)
        if simplified_expr != expr:
            simplified_expr = self.absorb([simplified_expr])[0]  # Recursive simplify
        result.append(simplified_expr)

    return result

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        import sys
        if sys.version_info[0] < 3:
            return tuple([str(t).encode('ascii') if t else t for t in namefunc()])
        else:
            return namefunc()
    except Exception as e:
        raise ValueError("An error occurred while processing tzname: " + str(e))

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        import some_module
        version_info = some_module.__version__
    except (ImportError, AttributeError):
        version_info = "Unknown"
    return version_info

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    try:
        if style == 'flat':
            return '.'.join(map(str, pieces))
        elif style == 'extended':
            return '-'.join(map(str, pieces))
        else:
            raise ValueError(f"Unsupported style: {style}")
    except Exception as e:
        raise RuntimeError(f"Error rendering version: {e}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if '+' in pieces:
        return '.'
    else:
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, list):
        raise ValueError("commands must be a list of command strings.")
    if not isinstance(args, list):
        raise ValueError("args must be a list of argument strings.")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary.")

    full_command = commands + args
    if verbose:
        print(f"Running command: {' '.join(full_command)}")

    try:
        with subprocess.Popen(
            full_command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT,
            text=True
        ) as process:
            output, _ = process.communicate()
            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, full_command, output=output)
            if verbose:
                print(f"Command output:\n{output}")
            return output
    except FileNotFoundError as e:
        raise FileNotFoundError(f"One of the command(s) {' '.join(commands)} was not found.") from e
    except subprocess.CalledProcessError as e:
        print(f"Command {' '.join(full_command)} failed with return code {e.returncode}")
        if not verbose:
            print(f"Command output:\n{e.output}")
        raise
    except Exception as e:
        raise Exception(f"An error occurred while running command {' '.join(full_command)}: {str(e)}") from e

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorator(func):
        try:
            if not callable(func):
                raise ValueError("The provided handler must be a callable function.")
            func._vcs_handler = vcs
            func._vcs_method = method
            return func
        except Exception as e:
            raise Exception(f"Failed to register VCS handler: {e}")
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    try:
        for obj in self.iter_objects():
            num_objects += 1
            is_valid = True
            if validate_objects and not obj.is_valid():
                is_valid = False
                if show_warnings:
                    print(f"Warning: Object {obj} is invalid.")
            if check_digests and not obj.check_digest():
                is_valid = False
                if show_warnings:
                    print(f"Warning: Digest check failed for object {obj}.")
            if is_valid:
                good_objects += 1
    except Exception as e:
        if show_warnings:
            print(f"Error during validation: {e}")

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        # Split the version into components
        parts = version.split('.')
        # Convert the last part to an integer and increment it
        parts[-1] = str(int(parts[-1]) + 1)
        # Join the parts back together
        return '.'.join(parts)
    except (ValueError, IndexError):
        raise ValueError("Invalid version format")

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list):
        raise TypeError("version_dirs must be a list of version directory names.")

    root_inventory = {}
    differing_digests = {}

    try:
        with open('root_inventory.json', 'r') as f:
            root_inventory = json.load(f)
    except FileNotFoundError:
        print("Root inventory not found. Skipping root inventory comparison.")
    except json.JSONDecodeError:
        print("Error decoding root inventory. Skipping root inventory comparison.")

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory.json')
        if not os.path.exists(inventory_path):
            print(f"Inventory not found for version {version_dir}.")
            continue

        try:
            with open(inventory_path, 'r') as f:
                inventory = json.load(f)
        except json.JSONDecodeError:
            print(f"Error decoding inventory for version {version_dir}.")
            continue

        for item, digest in inventory.items():
            if item in root_inventory and root_inventory[item] != digest:
                if item not in differing_digests:
                    differing_digests[item] = set()
                differing_digests[item].add(digest)

    return differing_digests

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    namaste_file = os.path.join(path, '0=ocfl_1.0')
    if os.path.isfile(namaste_file):
        with open(namaste_file, 'r') as f:
            content = f.read().strip()
        if content == 'ocfl_1.0':
            if os.path.isfile(os.path.join(path, 'inventory.json')):
                return 'root'
            else:
                return 'object'
    else:
        if os.path.isfile(path):
            return 'file'
        elif os.path.isdir(path):
            return 'unknown directory type'
    return 'not a valid OCFL path'

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary")
    if not isinstance(bug_ids, list) or not all(isinstance(bid, int) for bid in bug_ids):
        raise ValueError("bug_ids must be a list of integers")

    params['ids'] = ','.join(map(str, bug_ids))
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_value(key, value1, value2):
        if isinstance(value1, MappingNode) and isinstance(value2, MappingNode):
            value1_value_dict = {item[0].value: item[1] for item in value1.value}
            value2_value_dict = {item[0].value: item[1] for item in value2.value}
            merged_value_dict = {**value1_value_dict, **value2_value_dict}
            merged_value = [tuple(item) for item in merged_value_dict.items()]
            return MappingNode(value1.tag, merged_value)
        else:
            return value2

    merged_nodes = {}
    for key_node, value_node in nodes:
        if key_node.value in merged_nodes:
            merged_nodes[key_node.value] = merge_value(key_node, merged_nodes[key_node.value], value_node)
        else:
            merged_nodes[key_node.value] = value_node

    return [(ScalarNode(key_node.tag, key_value), value_node) for key_value, value_node in merged_nodes.items()]

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        actions = parser._actions
        flags = []
        for action in actions:
            if action.option_strings:
                flags.extend(action.option_strings)
        return ' '.join(flags)
    except AttributeError:
        raise ValueError("The provided object is not an argparse.ArgumentParser instance.")

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        flags = [action.option_strings for action in parser._actions if action.option_strings]
        flat_flags = [flag for sublist in flags for flag in sublist]
        return ' '.join(flat_flags)
    except AttributeError as e:
        raise ValueError("Provided object is not a valid argparse.ArgumentParser instance.") from e

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import borgmatic.commands.borgmatic
        import argparse
        import textwrap

        def get_subcommands(parser):
            subcommands = {}
            if isinstance(parser, argparse.ArgumentParser):
                for action in parser._actions:
                    if isinstance(action, argparse._SubParsersAction):
                        for name, subparser in action.choices.items():
                            subcommands[name] = get_subcommands(subparser)
            return subcommands

        def generate_completion_script(parser, parent_command=""):
            script = ""
            subcommands = get_subcommands(parser)

            if parent_command:
                script += f"_borgmatic_{parent_command}() {{\n"
            else:
                script += "_borgmatic() {\n"
                script += "    local cur prev opts subcommands\n"
                script += "    COMPREPLY=()\n"
                script += "    cur=\"${COMP_WORDS[COMP_CWORD]}\"\n"
                script += "    prev=\"${COMP_WORDS[COMP_CWORD-1]}\"\n"
                script += "    opts=\"\"\n"
                script += "    subcommands=\""

                for subcommand in subcommands:
                    script += f"{subcommand} "

                script += "\"\n\n"

            if subcommands:
                script += "    if [[ $cur == -* ]]; then\n"
                script += f"        COMPREPLY=( $(compgen -W \"${{opts}}\" -- ${{cur}}) )\n"
                script += "    else\n"
                script += f"        COMPREPLY=( $(compgen -W \"${{subcommands}}\" -- ${{cur}}) )\n"
                script += "    fi\n"
            else:
                script += f"    COMPREPLY=( $(compgen -W \"${{opts}}\" -- ${{cur}}) )\n"

            script += "    return 0\n"
            script += "}\n"

            if parent_command:
                script += f"complete -F _borgmatic_{parent_command} {parent_command}\n\n"
            else:
                script += "complete -F _borgmatic borgmatic\n\n"

            for subcommand, subparser in subcommands.items():
                script += generate_completion_script(subparser, f"{parent_command} {subcommand}")

            return script

        parser = borgmatic.commands.borgmatic.make_parsers()[0]
        return textwrap.dedent(generate_completion_script(parser))

    except Exception as e:
        return f"# Error generating bash completion script: {str(e)}"

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    try:
        if not isinstance(response, list):
            raise ValueError("Response must be a list.")
        if not isinstance(max_results, int) or max_results <= 0:
            raise ValueError("max_results must be a positive integer.")

        start = 0
        while start < len(response):
            yield response[start:start + max_results]
            start += max_results
    except Exception as e:
        raise e

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    try:
        return url.format(**url_args)
    except KeyError as e:
        raise ValueError(f"Missing argument '{e.args[0]}' for URL formatting") from e
    except TypeError as e:
        raise ValueError("URL formatting error: " + str(e)) from e

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if isinstance(val, str):
        return val.lower() in {'none', 'null', 'nil', 'n/a', ''}
    return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        for option_string in action.option_strings:
            flags.append(option_string)
    return ' '.join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Number must be non-negative.")
    if not alphabet:
        raise ValueError("Alphabet must not be empty.")
    if any(not isinstance(char, str) for char in alphabet):
        raise ValueError("All elements in alphabet must be strings.")
    if padding is not None and padding < 0:
        raise ValueError("Padding must be non-negative or None.")

    base = len(alphabet)
    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    result = ''.join(reversed(digits))
    if padding is not None:
        result = result.rjust(padding, alphabet[0])
    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    try:
        if not isinstance(flow_params, dict):
            raise ValueError("flow_params must be a dictionary.")
        if not isinstance(register_number, (int, str)):
            raise ValueError("register_number must be an integer or string.")
        if not isinstance(register_value, str):
            raise ValueError("register_value must be a string.")

        for key, value in flow_params.items():
            if isinstance(value, dict):
                _replace_register(value, register_number, register_value)
            elif value == register_value:
                flow_params[key] = register_number

    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

