def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        pattern = r'''(?:"((?:\\.|[^"\\])*)")|('((?:\\.|[^'\\])*)')|(\S+)'''
    elif platform == 0:  # Windows/CMD
        pattern = r'''("((?:\\.|[^"\\])*)")|('((?:\\.|[^'\\])*)')|(\S+)'''
    else:
        raise ValueError("Unsupported platform specified")

    args = []
    for match in re.finditer(pattern, s):
        for group in match.groups():
            if group:
                args.append(re.sub(r'\\(.)', r'\1', group))
                break

    return args

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        result = subprocess.run(['git', 'check-ignore', '-v', '-n'] + ignored, capture_output=True, text=True, check=True)
        ignored_files = set()
        for line in result.stdout.splitlines():
            parts = line.split()
            if len(parts) > 1:
                ignored_files.add(parts[-1])
        return ', '.join(sorted(ignored_files))
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Error running git command: " + e.stderr.strip()) from e
    except Exception as e:
        raise RuntimeError("An unexpected error occurred: " + str(e)) from e

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        value, unit = frequency.split()
        value = int(value)
    except ValueError:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    unit = unit.lower().strip('s')  # Remove plural 's' if present
    if unit == 'week':
        return datetime.timedelta(weeks=value)
    elif unit == 'day':
        return datetime.timedelta(days=value)
    elif unit == 'hour':
        return datetime.timedelta(hours=value)
    elif unit == 'minute':
        return datetime.timedelta(minutes=value)
    elif unit == 'second':
        return datetime.timedelta(seconds=value)
    else:
        raise ValueError(f"Unknown frequency unit: {unit}")

