    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise ValueError("Pattern must be a string")
    if strip:
        pattern = pattern.strip()
    try:
        regex_pattern = re.compile(pattern)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {e}")
    return regex_pattern

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    try:
        if isinstance(commands, str):
            commands = [commands]

        if not isinstance(commands, list):
            raise ValueError("Commands must be a string or a list of strings.")

        cmd = commands + args
        if verbose:
            print("Running command:", ' '.join(cmd))

        stderr = subprocess.DEVNULL if hide_stderr else None
        result = subprocess.run(cmd, cwd=cwd, env=env, stderr=stderr, check=True, text=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with return code {e.returncode}: {e.stderr}")
        raise
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        raise

