def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mu = 0.2
    sigma = 0.1
    try:
        return (1 / (sigma * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((x - mu) / sigma) ** 2)
    except Exception as e:
        raise ValueError(f"An error occurred during Gaussian computation: {e}")

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser
    import os

    configurations = {}
    log_records = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        if not os.path.isfile(filename):
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Configuration file not found: {filename}", args=(), exc_info=None))
            continue

        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as file:
                config.read_file(file)
        except Exception as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Error reading configuration file: {filename}", args=(), exc_info=e))
            continue

        # Resolve environment variables if requested
        if resolve_env:
            for section in config.sections():
                for key, value in config.items(section):
                    try:
                        config.set(section, key, os.path.expandvars(value))
                    except Exception as e:
                        log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Error expanding environment variables in {filename}: {section}.{key}", args=(), exc_info=e))

        # Apply overrides
        for section, settings in overrides.items():
            if section in config:
                for key, value in settings.items():
                    config.set(section, key, value)

        configurations[filename] = config

    return configurations, log_records

