def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        if self._scale is None:
            raise AttributeError("Graph scale is not set.")
        return self._scale
    else:
        if self._scale is None or self._scale == 0:
            raise ValueError("Graph has unknown or zero scale, cannot rescale.")
        try:
            other = float(other)
        except ValueError:
            raise TypeError("Scale factor must be a numeric value.")

        scale_factor = other / self._scale
        if hasattr(self, 'coordinates') and self.coordinates:
            for i in range(len(self.coordinates)):
                self.coordinates[i][-1] *= scale_factor
            if hasattr(self, 'errors') and self.errors:
                for i in range(len(self.errors)):
                    self.errors[i][-1] *= scale_factor
        self._scale = other

def verifyObject(iface, candidate, tentative=False):
    from zope.interface import Invalid, providedBy
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"{candidate} does not declare that it provides {iface}")

    required_methods = iface.names(all=False, callable=True)
    for method_name in required_methods:
        if not hasattr(candidate, method_name):
            errors.append(f"{candidate} does not define method {method_name}")
        else:
            method = getattr(iface, method_name)
            candidate_method = getattr(candidate, method_name)
            if method.signature and not method.signature.check(candidate_method):
                errors.append(f"Method {method_name} of {candidate} does not have the correct signature")

    required_attributes = iface.names(all=False, callable=False)
    for attr_name in required_attributes:
        if not hasattr(candidate, attr_name):
            errors.append(f"{candidate} does not define attribute {attr_name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Multiple interface verification failures:\n" + "\n".join(errors))

    return True

