    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    conditionally_required = []
    for option in options_spec:
        required_when = option.get('required_when')
        if required_when:
            condition = required_when.get('condition')
            if condition:
                try:
                    if eval(condition, {}, args):
                        conditionally_required.append(option['name'])
                except Exception as e:
                    # Handle any exceptions that might occur during evaluation
                    # of the condition safely.
                    print(f"Error evaluating condition for {option['name']}: {e}")
    return conditionally_required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    try:
        for arg, value in args.items():
            if isinstance(value, str) and 'length' in arg:
                length = int(arg.split('_')[-1])  # Assuming the pattern is like 'value_length_10'
                if len(value) > length:
                    raise ValueError(f"The value for '{arg}' is longer than the specified length of {length}.")
    except (ValueError, TypeError) as e:
        print(f"An error occurred: {e}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg, value in args.items():
        if hasattr(self, f"{arg}_choices"):
            choices = getattr(self, f"{arg}_choices")
            if value not in choices:
                raise ValueError(f"Invalid value for {arg}: {value}. Choices are {choices}.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not hasattr(self, 'min_args') or not hasattr(self, 'max_args'):
        raise AttributeError("Class must define min_args and max_args attributes.")

    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple.")

    if len(args) < self.min_args:
        raise ValueError(f"Too few arguments: expected at least {self.min_args}, got {len(args)}.")

    if len(args) > self.max_args:
        raise ValueError(f"Too many arguments: expected at most {self.max_args}, got {len(args)}.")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    try:
        for key, value in args.items():
            if key.startswith('control_'):
                control_args[key] = value
            elif key.startswith('custom_'):
                nested_args[key[len('custom_'):]] = value
            else:
                nested_args[key] = value
    except AttributeError:
        raise ValueError("Expected args to be a dictionary")

    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        extra_vars = []

    try:
        for var in extra_vars:
            if isinstance(var, dict):
                vars_dict.update(var)
            else:
                raise ValueError("Each item in extra_vars must be a dictionary.")
    except Exception as e:
        raise ValueError("An error occurred while merging extra-vars: " + str(e))

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import shlex

    if not playbook_path:
        raise ValueError("Playbook path is required.")

    cmd = ['ansible-playbook', playbook_path]

    if verbose:
        cmd.extend(['-v'] * verbose)

    if extra_vars:
        extra_vars_str = ','.join([f'{k}={v}' for k, v in extra_vars.items()])
        cmd.extend(['--extra-vars', extra_vars_str])

    if ansible_args:
        for key, value in ansible_args.items():
            flag = f"--{key}"
            if value is not None:
                cmd.extend([flag, shlex.quote(str(value))])
            else:
                cmd.append(flag)

    try:
        result = subprocess.run(cmd, check=True, text=True, capture_output=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Ansible playbook failed with return code {e.returncode}.\nError: {e.stderr}") from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while running ansible-playbook: {e}") from e

