def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    from collections import defaultdict

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    plugin_spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
    flat_dict = defaultdict(dict)

    try:
        with open(plugin_spec_path, 'r') as file:
            plugin_spec = json.load(file)
            flat_dict = flatten_dict(plugin_spec)
    except FileNotFoundError:
        print(f"Error: The file 'plugin_spec.json' was not found in the directory '{plugin_dir}'.")
    except json.JSONDecodeError:
        print(f"Error: The file 'plugin_spec.json' in the directory '{plugin_dir}' is not a valid JSON file.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    return flat_dict

